  static String getCategory(String cat, String lang) {
    final code = lang.toLowerCase();
    if (code == 'fr') return cat;
    final row = _categories[cat];
    if (row == null) return cat;
    final idx = _langs.indexOf(code);
    if (idx < 0) return cat;
    final parts = row.split('|');
    return (idx < parts.length && parts[idx].isNotEmpty) ? parts[idx] : cat;
  }

