  static String? getBadgeTitle(String id, String lang) {
    final code = lang.toLowerCase();
    if (code == 'fr') return null;
    final row = _badgeTitles[id];
    if (row == null) return null;
    final idx = _langs.indexOf(code);
    if (idx < 0) return null;
    final parts = row.split('|');
    return (idx < parts.length && parts[idx].isNotEmpty) ? parts[idx] : null;
  }

  static String? getBadgeDescription(String id, String lang) {
    final code = lang.toLowerCase();
    if (code == 'fr') return null;
    final row = _badgeDescs[id];
    if (row == null) return null;
    final idx = _langs.indexOf(code);
    if (idx < 0) return null;
    final parts = row.split('|');
    return (idx < parts.length && parts[idx].isNotEmpty) ? parts[idx] : null;
  }

  static BadgeTranslation? getTranslation(String id, String lang) {
    final t = getBadgeTitle(id, lang);
    final d = getBadgeDescription(id, lang);
    if (t == null && d == null) return null;
    return BadgeTranslation(title: t ?? '', description: d ?? '');
  }
}
